"""Section 1256: the same option trade, taxed two ways, depending on the underlying.

WHY this exists: an index option on the S&P 500 and an option on an S&P 500 ETF can be
built to have the same payoff, the same premium and the same pre-tax P&L -- and they are
taxed under two different regimes. One is marked to market on the last business day of the
year whether or not you closed it, and splits every dollar 60% long-term / 40% short-term
regardless of how long you held it. The other is an ordinary equity option: nothing is
recognised until you close, and a position held for six weeks is 100% short-term.

TWO RULES, and both of them surprise people:

  MARK-TO-MARKET.  IRC 1256(a)(1): a section 1256 contract held at the close of the taxable
  year "shall be treated as sold for its fair market value on the last business day of such
  taxable year". A position you never closed produces a taxable gain. There is no election
  to defer it (outside the hedging and mixed-straddle rules).

  60/40.  IRC 1256(a)(3): 40 percent short-term, 60 percent long-term, "regardless of how
  long you actually held the property" (Pub 550's phrasing). At a 37/20 rate pair the
  blended rate is 26.8% instead of 37.0% -- and that is BEFORE any view on whether the
  timing helps or hurts.

WHAT QUALIFIES (IRC 1256(b)(1)): regulated futures contracts, foreign currency contracts,
nonequity options, dealer equity options, dealer securities futures contracts.
`classify()` carries the authority for each instrument this library is willing to state,
and returns 'unclear' rather than guessing where the primary sources stop.

Usage:
    from section_1256 import make_option_book, compare_regimes, classify
    print(classify("broad_based_index_option"))
    print(compare_regimes(*make_option_book(), short_rate=0.37, long_rate=0.20))

This is a MODELLING tool for backtests. It is not tax advice. Rules change; check current
law with a professional before relying on any of it.
"""
from __future__ import annotations

import numpy as np
import pandas as pd

LONG_FRACTION = 0.60        # IRC 1256(a)(3)(B)
SHORT_FRACTION = 0.40       # IRC 1256(a)(3)(A)
CONTRACT_MULTIPLIER = 100.0

# Every entry is a claim with a source. 'unclear' means the primary sources this library
# read do not settle it, and the caller has to decide with a professional.
CLASSIFICATION = {
    "regulated_futures": (
        "section_1256",
        "IRC 1256(b)(1)(A); Pub 550 (2025) 'Regulated futures contract' -- daily margin "
        "mark plus a qualified board or exchange"),
    "foreign_currency_contract": (
        "section_1256",
        "IRC 1256(b)(1)(B); Pub 550 (2025) 'Foreign currency contract'. Note IRC 988 can "
        "make the gain ORDINARY; check it before applying 60/40"),
    "broad_based_index_option": (
        "section_1256",
        "IRC 1256(b)(1)(C) + 1256(g)(3) nonequity option + 1256(g)(6) equity option. "
        "Pub 550 (2025) is explicit: 'Nonequity options include ... broad-based stock "
        "index options. A broad-based stock index is based on the value of a group of "
        "diversified stocks or securities (such as the Standard and Poor's 500 index).'"),
    "narrow_based_index_option": (
        "equity_option",
        "IRC 1256(g)(6): an option on a group of stocks is an equity option if the group "
        "meets the narrow-based test of Exchange Act 3(a)(55) -- 9 or fewer components, or "
        "one over 30% of weighting, or the top five over 60%, or the thin-volume test"),
    "single_stock_option": (
        "equity_option",
        "IRC 1256(g)(6)(A): an option 'to buy or sell stock'"),
    "etf_option": (
        "unclear",
        "WARNING: universally treated as an equity option in practice, because an ETF share "
        "is stock or an interest treated as stock, so 1256(g)(6)(A) reaches it. But neither "
        "IRC 1256(g) nor Pub 550 (2025) names exchange-traded funds, and this library found "
        "no published IRS ruling squarely on the point (checked 2026-09-09). Get advice"),
    "securities_futures_contract": (
        "not_1256",
        "IRC 1256(b)(2)(A) and Pub 550 (2025) 'Securities Futures Contracts': excluded "
        "unless it is a dealer securities futures contract; a contract to SELL is always "
        "short-term"),
    "swap": (
        "not_1256",
        "IRC 1256(b)(2)(B): interest rate, currency, basis, commodity, equity, equity index "
        "and credit default swaps, caps, floors 'or similar agreements' are excluded"),
}


def classify(instrument: str) -> dict:
    """Regime plus the authority for it. Raises on an instrument this library has not read."""
    if instrument not in CLASSIFICATION:
        raise ValueError(f"unknown instrument {instrument!r}; this module states a regime only "
                         f"where it has a source. Known: {sorted(CLASSIFICATION)}")
    regime, authority = CLASSIFICATION[instrument]
    return {"instrument": instrument, "regime": regime, "authority": authority,
            "verified_on": "2026-09-09"}


def sixty_forty(gain: float) -> dict[str, float]:
    """IRC 1256(a)(3): 60% long-term, 40% short-term, regardless of holding period."""
    return {"long": float(gain) * LONG_FRACTION, "short": float(gain) * SHORT_FRACTION}


def last_business_day(year: int) -> pd.Timestamp:
    """IRC 1256(a)(1) marks on the LAST BUSINESS DAY of the tax year, not on December 31.

    Weekday rule only. If the exchange closes on the last weekday of the year -- it has
    happened, for national days of mourning -- the statutory date moves and this helper does
    not know it. Check the exchange calendar for the years your backtest actually spans.
    """
    return pd.Timestamp(f"{int(year)}-12-31") - pd.offsets.BDay(0) \
        if pd.Timestamp(f"{int(year)}-12-31").weekday() < 5 \
        else pd.Timestamp(f"{int(year)}-12-31") - pd.offsets.BDay(1)


def is_long_term(open_date, close_date) -> bool:
    """More than one calendar year (IRC 1222). Used by the EQUITY-option path only."""
    return pd.Timestamp(close_date) > pd.Timestamp(open_date) + pd.DateOffset(years=1)


# --------------------------------------------------------------------------- recognition
def _check(positions: pd.DataFrame) -> pd.DataFrame:
    need = ("open_date", "close_date", "qty", "open_price", "close_price")
    missing = [c for c in need if c not in positions.columns]
    if missing:
        raise ValueError(f"positions is missing column(s) {missing}; needs {list(need)}")
    p = positions.copy()
    p["open_date"] = pd.to_datetime(p["open_date"])
    p["close_date"] = pd.to_datetime(p["close_date"])
    closed = p["close_date"].notna()
    if p.loc[closed, "close_price"].isna().any():
        raise ValueError("a closed position needs a close_price")
    if (p["close_date"] < p["open_date"]).any():
        raise ValueError("close_date is before open_date")
    return p


def recognise_1256(positions: pd.DataFrame, marks: pd.DataFrame,
                   multiplier: float = CONTRACT_MULTIPLIER) -> pd.DataFrame:
    """Year-by-year recognised gain under IRC 1256: year-end marks plus the closing trade.

    `marks` has columns (position, year, price) -- the fair market value on the last
    business day of that year, for each year the position is still open. Each mark becomes
    the reference for the next period, exactly as Pub 550's own worked example does.
    """
    p = _check(positions)
    for c in ("position", "year", "price"):
        if c not in marks.columns:
            raise ValueError(f"marks is missing column {c!r}; needs position, year, price")
    m = {(r.position, int(r.year)): float(r.price) for r in marks.itertuples(index=False)}
    last_marked = {}
    for pos_id, year in m:
        last_marked[pos_id] = max(last_marked.get(pos_id, year), year)
    rows = []
    for i, pos in p.iterrows():
        ref = float(pos["open_price"])
        end_year = (int(pos["close_date"].year) if pd.notna(pos["close_date"])
                    else last_marked.get(i, int(pos["open_date"].year) - 1) + 1)
        for year in range(int(pos["open_date"].year), end_year):
            if (i, year) not in m:
                continue
            mk = m[(i, year)]
            rows.append({"position": i, "year": year, "event": "year_end_mark",
                         "gain": (mk - ref) * float(pos["qty"]) * multiplier})
            ref = mk
        if pd.notna(pos["close_date"]):
            rows.append({"position": i, "year": int(pos["close_date"].year), "event": "close",
                         "gain": (float(pos["close_price"]) - ref) * float(pos["qty"])
                         * multiplier})
    ev = pd.DataFrame(rows, columns=["position", "year", "event", "gain"])
    if ev.empty:
        out = pd.DataFrame(columns=["recognised", "long_term", "short_term"], dtype=float)
    else:
        out = ev.groupby("year")["gain"].sum().to_frame("recognised")
        out["long_term"] = out["recognised"] * LONG_FRACTION
        out["short_term"] = out["recognised"] * SHORT_FRACTION
    out.attrs["events"] = ev
    return out


def recognise_equity_option(positions: pd.DataFrame,
                            multiplier: float = CONTRACT_MULTIPLIER) -> pd.DataFrame:
    """Year-by-year recognised gain for an equity option: nothing until it is closed."""
    p = _check(positions)
    rows = []
    for i, pos in p.iterrows():
        if pd.isna(pos["close_date"]):
            continue                              # still open: nothing is recognised
        g = (float(pos["close_price"]) - float(pos["open_price"])) * float(pos["qty"]) \
            * multiplier
        term = "long_term" if is_long_term(pos["open_date"], pos["close_date"]) else "short_term"
        rows.append({"position": i, "year": int(pos["close_date"].year), "event": "close",
                     "gain": g, "term": term})
    ev = pd.DataFrame(rows, columns=["position", "year", "event", "gain", "term"])
    if ev.empty:
        out = pd.DataFrame(columns=["recognised", "long_term", "short_term"])
        out.attrs["events"] = ev
        return out
    out = ev.pivot_table(index="year", columns="term", values="gain", aggfunc="sum",
                         fill_value=0.0)
    for col in ("long_term", "short_term"):
        if col not in out.columns:
            out[col] = 0.0
    out = out.loc[:, ["long_term", "short_term"]]
    out.insert(0, "recognised", out["long_term"] + out["short_term"])
    out.columns.name = None
    out.attrs["events"] = ev
    return out


def tax_schedule(schedule: pd.DataFrame, short_rate: float, long_rate: float) -> pd.DataFrame:
    """Add a per-year tax column at rates the CALLER states. No defaults live here."""
    for name, r in (("short_rate", short_rate), ("long_rate", long_rate)):
        if not 0.0 <= float(r) <= 1.0:
            raise ValueError(f"{name}={r} is not a rate in [0, 1]")
    out = schedule.copy()
    out["tax"] = out["short_term"] * float(short_rate) + out["long_term"] * float(long_rate)
    return out


def blended_rate(short_rate: float, long_rate: float) -> float:
    """The 60/40 blended rate. The one number people quote, and it is only this simple for
    a NET GAIN: on a net loss the same arithmetic runs in the other direction."""
    return SHORT_FRACTION * float(short_rate) + LONG_FRACTION * float(long_rate)


# --------------------------------------------------------------------------- demo book
def make_option_book(seed: int = 20260909, months: int = 38, start: str = "2022-01-03",
                     p0: float = 20.0, sigma: float = 0.40, drift: float = 0.45,
                     hold_days: int = 42, qty: float = 10.0):
    """One seeded premium series and one trade schedule, usable under BOTH regimes.

    The whole point is that the economics are identical by construction: same premiums,
    same dates, same sizes. Only the tax regime differs. The final position is deliberately
    left open, because that is the case the two regimes disagree about most sharply.
    """
    rng = np.random.default_rng(seed)
    n = months * 21 + 1
    dates = pd.bdate_range(start, periods=n)
    step = rng.normal(drift / 252.0 - 0.5 * sigma**2 / 252.0, sigma / np.sqrt(252.0), n)
    px = pd.Series(p0 * np.exp(np.cumsum(step)), index=dates)

    rows = []
    for i in range(0, n - hold_days, 21):
        rows.append({"open_date": dates[i], "close_date": dates[i + hold_days],
                     "qty": qty, "open_price": float(px.iloc[i]),
                     "close_price": float(px.iloc[i + hold_days])})
    # ...plus one long-dated position, opened early and never closed. It is the whole
    # disagreement between the two regimes: 1256 marks it at every year end it survives,
    # an equity option recognises nothing until it is sold.
    rows.append({"open_date": dates[hold_days], "close_date": pd.NaT, "qty": qty,
                 "open_price": float(px.iloc[hold_days]), "close_price": np.nan})
    positions = pd.DataFrame(rows).sort_values("open_date").reset_index(drop=True)

    mrows = []
    for i, pos in positions.iterrows():
        last_year = (int(pos["close_date"].year) - 1 if pd.notna(pos["close_date"])
                     else int(dates[-1].year))
        for year in range(int(pos["open_date"].year), last_year + 1):
            d = last_business_day(year)
            if d < pos["open_date"] or d > dates[-1]:
                continue
            mrows.append({"position": i, "year": year,
                          "price": float(px.asof(d))})
    marks = pd.DataFrame(mrows, columns=["position", "year", "price"])
    positions.attrs["final_price"] = float(px.iloc[-1])
    positions.attrs["prices"] = px
    return positions, marks


def pretax_pnl(positions: pd.DataFrame, mark: float,
               multiplier: float = CONTRACT_MULTIPLIER) -> float:
    """Economic P&L of the book, open positions marked at `mark`. No tax rules in it."""
    p = _check(positions)
    close = p["close_price"].fillna(float(mark))
    return float(((close - p["open_price"]) * p["qty"] * multiplier).sum())


def compare_regimes(positions: pd.DataFrame, marks: pd.DataFrame, short_rate: float,
                    long_rate: float, multiplier: float = CONTRACT_MULTIPLIER) -> dict:
    """The same book under both regimes, plus the pre-tax P&L both of them describe."""
    mark = positions.attrs.get("final_price")
    if mark is None:
        raise ValueError("positions.attrs['final_price'] is needed to mark the open position")
    a = tax_schedule(recognise_1256(positions, marks, multiplier), short_rate, long_rate)
    b = tax_schedule(recognise_equity_option(positions, multiplier), short_rate, long_rate)
    return {"section_1256": a, "equity_option": b,
            "pretax_pnl": pretax_pnl(positions, mark, multiplier),
            "tax_1256": float(a["tax"].sum()), "tax_equity": float(b["tax"].sum()),
            "blended_rate": blended_rate(short_rate, long_rate)}


def main() -> None:
    short_rate, long_rate = 0.37, 0.20
    print("Section 1256 -- two economically identical option strategies, two tax regimes")
    print(f"  IRC 1256(a)(3): {SHORT_FRACTION:.0%} short-term / {LONG_FRACTION:.0%} long-term, "
          f"regardless of holding period")
    print(f"  ASSUMED rates (inputs, not defaults): short {short_rate:.0%}, "
          f"long {long_rate:.0%} -> 60/40 blended {blended_rate(short_rate, long_rate):.1%}")

    for name in ("broad_based_index_option", "etf_option"):
        c = classify(name)
        print(f"  {name:<26} -> {c['regime']}")

    positions, marks = make_option_book()
    mark = positions.attrs["final_price"]
    n_open = int(positions["close_date"].isna().sum())
    res = compare_regimes(positions, marks, short_rate, long_rate)
    print()
    print(f"  seeded book: {len(positions)} positions of {positions['qty'].iloc[0]:g} "
          f"contracts, 42-business-day holds, {n_open} still open at {mark:.4f}")
    print(f"  pre-tax P&L, IDENTICAL under both regimes: {res['pretax_pnl']:,.2f}")

    print()
    print("  year   1256 recognised   1256 tax    equity recognised   equity tax")
    years = sorted(set(res["section_1256"].index) | set(res["equity_option"].index))
    for y in years:
        a = res["section_1256"].reindex([y]).fillna(0.0).iloc[0]
        b = res["equity_option"].reindex([y]).fillna(0.0).iloc[0]
        print(f"  {y}   {a['recognised']:>15,.2f}{a['tax']:>11,.2f}"
              f"{b['recognised']:>21,.2f}{b['tax']:>13,.2f}")
    print(f"  TOTAL  {res['section_1256']['recognised'].sum():>15,.2f}"
          f"{res['tax_1256']:>11,.2f}{res['equity_option']['recognised'].sum():>21,.2f}"
          f"{res['tax_equity']:>13,.2f}")

    rec_a = float(res["section_1256"]["recognised"].sum())
    rec_b = float(res["equity_option"]["recognised"].sum())
    ev = res["section_1256"].attrs["events"]
    open_id = positions.index[positions["close_date"].isna()][0]
    never = float(ev.loc[(ev["position"] == open_id)
                         & (ev["event"] == "year_end_mark"), "gain"].sum())
    print()
    print(f"  the position never closed books {never:,.2f} under 1256 across "
          f"{int((ev['position'] == open_id).sum())} year ends, and 0.00 as an equity option")
    print(f"  so 1256 has already taxed {rec_a:,.2f} of a book that has made "
          f"{res['pretax_pnl']:,.2f}")
    eq_terms = res["equity_option"].attrs["events"]["term"].value_counts().to_dict()
    print(f"  equity-option closes by character: {eq_terms}")

    print()
    print(f"  effective rate on recognised income:")
    print(f"    section 1256   {res['tax_1256']:>10,.2f} / {rec_a:>10,.2f} = "
          f"{res['tax_1256'] / rec_a:.1%}  (= the 60/40 blended rate, exactly)")
    print(f"    equity option  {res['tax_equity']:>10,.2f} / {rec_b:>10,.2f} = "
          f"{res['tax_equity'] / rec_b:.1%}  (= the short-term rate, exactly)")
    print(f"  RATE effect, same base: 60/40 on {rec_a:,.2f} saves "
          f"{rec_a * (short_rate - blended_rate(short_rate, long_rate)):,.2f}")
    print(f"  TIMING effect: 1256 recognised {rec_a - rec_b:,.2f} more income, years earlier, "
          f"with no cash from a sale")
    print(f"  NET on this book: 1256 pays {res['tax_1256'] - res['tax_equity']:,.2f} "
          f"{'more' if res['tax_1256'] > res['tax_equity'] else 'less'} tax in total")

    print()
    print("  and the direction reverses for a position held over a year:")
    held = pd.DataFrame([{"open_date": "2023-01-04", "close_date": "2024-06-03", "qty": 1.0,
                          "open_price": 100.0, "close_price": 200.0}])
    long_1256 = float(tax_schedule(recognise_1256(held, pd.DataFrame(
        [{"position": 0, "year": 2023, "price": 100.0}]), 100.0),
        short_rate, long_rate)["tax"].sum())
    long_eq = float(tax_schedule(recognise_equity_option(held, 100.0),
                                 short_rate, long_rate)["tax"].sum())
    print(f"    one 10,000 gain held 516 days: 1256 {long_1256:,.2f} vs equity option "
          f"{long_eq:,.2f} -- 60/40 costs MORE")

    print()
    print("  dated -- Rev. Rul. 2026-16 (read 2026-09-09) adds ICE Endex to the qualified")
    print("  boards or exchanges of 1256(g)(7)(C) for contracts entered on or after "
          "2026-09-01.")
    print()
    print("RULE: 1256 marks open positions on the last business day of the year and splits "
          "every dollar 60/40, so the underlying decides the tax, not the payoff.")


if __name__ == "__main__":
    main()
